"""Exact unselected truck-following plans; every fallback preserves the law and cell."""
from __future__ import annotations

CASES=('probe_1','probe_2')
CANDIDATES=('primary','fallback1','fallback2','fallback3')
TARGET_GAP_M={'probe_1':165.,'probe_2':140.}
BASE={'ego_target_speed_mps':8.,'lead_target_speed_mps':8.,
      'gap_controller_gain_per_s':.35,'overview_fov_deg':90.,
      'overview_height_m':7.,'rate_hz':20,'duration_s':24}
CHANGES={
    'primary':{},
    'fallback1':{'ego_target_speed_mps':7.5},
    'fallback2':{'lead_target_speed_mps':8.5,'gap_controller_gain_per_s':.5},
    'fallback3':{'overview_fov_deg':110.,'overview_height_m':10.},
}
TRIGGERS={
    'fallback1':{'metric':'min_surface_gap_m','op':'<','threshold':152.4,
        'source':'original full-body truck footprints, Native road elevation and 480-frame source hashes'},
    'fallback2':{'metric':'max_gap_shortfall_m','op':'>','threshold':2.,
        'source':'original full-body truck footprints and target gap over joined Native frames'},
    'fallback3':{'metric':'min_projected_truck_frame_margin_px','op':'<','threshold':40.,
        'source':'original truck 3D bodies, surveyed overview camera calibration and decoded video frame join'},
}


def parameters(case:str,candidate:str)->dict:
    if case not in CASES or candidate not in CANDIDATES:
        raise ValueError('Unknown C102372 case or candidate')
    return {'case':case,'candidate':candidate,'target_gap_m':TARGET_GAP_M[case],
            'knobs':BASE|CHANGES[candidate],'fallback_trigger':TRIGGERS.get(candidate),
            'law_id':'NRS-484B-127-2','cell_id':'C102372','actor':'heavy_vehicle_driver',
            'comparison_variable':'following_surface_gap_ft',
            'status':'unselected_native_plan','legal_verdict_claimed':False}


def speed_requests(plan:dict,observed_gap_m:float)->tuple[float,float]:
    """Follow at measured gap; distinct fallbacks change speed and correction."""
    knobs=plan['knobs']
    correction=knobs['gap_controller_gain_per_s']*(observed_gap_m-plan['target_gap_m'])
    ego=max(0.,min(knobs['ego_target_speed_mps'],knobs['ego_target_speed_mps']+correction))
    lead=knobs['lead_target_speed_mps']
    return round(ego,5),round(lead,5)

"""Source-hashed truck gap, gap-control and camera-projection fallback metrics."""
from __future__ import annotations
import hashlib
import json
import math
from pathlib import Path
import subprocess
import xml.etree.ElementTree as ET

from engineering import TARGET_GAP_M,TRIGGERS
from measure_gap import measure,road_distance

SOURCES=('native_samples.jsonl','following_context.json','road.xodr',
         'video_frames.jsonl','camera_context.json','overview.mkv')


def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def rows(path):return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def decoded_video(path):
    result=subprocess.run(['ffprobe','-v','error','-count_frames','-select_streams','v:0',
        '-show_entries','stream=width,height,nb_read_frames','-of','json',str(path)],
        capture_output=True,text=True,timeout=120)
    if result.returncode:raise ValueError('Original overview decode failed')
    stream=json.loads(result.stdout)['streams'][0]
    return int(stream['width']),int(stream['height']),int(stream['nb_read_frames'])


def margin(point,pose,camera):
    x,y,z=pose['xyz_m'];yaw=math.radians(pose['yaw_deg']);pitch=math.radians(pose['pitch_deg'])
    dx,dy,dz=point[0]-x,point[1]-y,point[2]-z
    forward=dx*math.cos(pitch)*math.cos(yaw)+dy*math.cos(pitch)*math.sin(yaw)+dz*math.sin(pitch)
    width,height=camera['width'],camera['height']
    if forward<=.01:return -float(max(width,height))
    right=-dx*math.sin(yaw)+dy*math.cos(yaw)
    up=-dx*math.sin(pitch)*math.cos(yaw)-dy*math.sin(pitch)*math.sin(yaw)+dz*math.cos(pitch)
    focal=width/(2*math.tan(math.radians(camera['fov_deg'])/2))
    u=width/2+focal*right/forward;v=height/2-focal*up/forward
    return min(u,width-u,v,height-v)


def extract(root,case):
    root=Path(root).resolve()
    if case not in TARGET_GAP_M and case!='two_lane_exception':
        raise ValueError('Unknown exact truck case')
    manifest_path=root/'trigger-source-manifest.json'
    if not manifest_path.is_file():raise ValueError('Missing trigger source manifest')
    declared=json.loads(manifest_path.read_text())
    if declared.get('format')!='c102372-truck-trigger-sources-v1' or set(
            declared.get('sha256',{}))!=set(SOURCES):
        raise ValueError('Incomplete original trigger source hashes')
    for name in SOURCES:
        path=root/name
        if not path.is_file() or sha(path)!=declared['sha256'][name]:
            raise ValueError('Trigger source missing or changed: '+name)
    if case=='two_lane_exception':
        from two_lane_exception import measure as measure_two_lane
        measurement=measure_two_lane(root)
        target_gap=140.
    else:
        measurement=measure(root)
        target_gap=TARGET_GAP_M[case]
    native=rows(root/'native_samples.jsonl');mapping=rows(root/'video_frames.jsonl')
    if len(native)!=480 or len(mapping)!=480:raise ValueError('Full 480-frame trigger join required')
    camera=json.loads((root/'camera_context.json').read_text())
    if camera.get('name')!='overview' or camera.get('source_kind') not in (
            'synthetic_cpu_camera_emulation','original_native_camera_readback'):
        raise ValueError('Overview camera readback absent')
    for key in ('width','height','fov_deg'):
        if type(camera.get(key)) not in (int,float):raise ValueError('Overview calibration absent')
    if decoded_video(root/'overview.mkv')!=(camera['width'],camera['height'],480):
        raise ValueError('Original overview dimensions or frame count differ')
    road=ET.parse(root/'road.xodr').getroot().find('road')
    profile=road.findall('elevationProfile/elevation')
    deficits=[];margins=[];prior=None
    for index,(row,join) in enumerate(zip(native,mapping)):
        frame=row.get('carla_frame')
        if (row.get('native_frame'),join.get('native_frame'),join.get('video_frame'),
                join.get('carla_frame'))!=(index,index,index,frame) or type(frame) is not int or \
                (prior is not None and frame<=prior):
            raise ValueError('Original truck/camera frame identity differs')
        prior=frame
        ego=row['ego'];lead=row['lead']
        front=max(p[0] for p in ego['body_xy_m'])
        rear=min(p[0] for p in lead['body_xy_m'])
        deficits.append(max(0.,target_gap-road_distance(front,rear,profile)))
        pose=row.get('overview_camera_pose')
        if not isinstance(pose,dict) or not all(key in pose for key in ('xyz_m','yaw_deg','pitch_deg')):
            raise ValueError('Original per-frame camera pose absent')
        for actor in (ego,lead):
            vertices=actor.get('body_vertices_m')
            if not isinstance(vertices,list) or len(vertices)<8:
                raise ValueError('Original full truck 3D body absent')
            expected={(round(p[0],4),round(p[1],4)) for p in actor['body_xy_m']}
            observed={(round(p[0],4),round(p[1],4)) for p in vertices}
            if expected!=observed:raise ValueError('Original 2D/3D truck body differs')
            margins.extend(margin(point,pose,camera) for point in vertices)
    metrics={'format':'c102372-source-bound-fallback-metrics-v1',
        'source_kind':json.loads((root/'following_context.json').read_text())['source_kind'],
        'case':case,'min_surface_gap_m':measurement['min_surface_gap_m'],
        'max_gap_shortfall_m':round(max(deficits),5),
        'min_projected_truck_frame_margin_px':round(min(margins),5),
        'sources':declared['sha256'],
        'limitations':['projection is not pixel visibility',
                       'synthetic conditions and body geometry do not establish a legal verdict']}
    if not all(math.isfinite(metrics[trigger['metric']]) for trigger in TRIGGERS.values()):
        raise ValueError('Nonfinite truck fallback metric')
    return metrics


def evaluate(candidate,metrics,path,expected_sha256,diagnostic=False):
    if candidate not in TRIGGERS:raise ValueError('Only fallbacks have triggers')
    raw=Path(path).read_bytes()
    if hashlib.sha256(raw).hexdigest()!=expected_sha256:
        raise ValueError('Fallback metric source hash differs')
    record=json.loads(raw)
    permitted=('native_observation','synthetic_cpu_fixture') if diagnostic else ('native_observation',)
    if record!=metrics or record.get('source_kind') not in permitted:
        raise ValueError('Fallback metrics are not bound to original Native source')
    trigger=TRIGGERS[candidate];value=record.get(trigger['metric'])
    if type(value) not in (int,float):raise ValueError('Measured trigger value absent')
    return value<trigger['threshold'] if trigger['op']=='<' else value>trigger['threshold']

"""Four planned Native constructions for the same-cell two-lane exception."""
from __future__ import annotations
import hashlib
import json
import xml.etree.ElementTree as ET
from engineering import CANDIDATES,parameters
from two_lane_exception import two_lane_open_drive

CASE='two_lane_exception'
ASSIGNMENT='training__C102372__NRS-484B-127-2__heavy_vehicle_driver'


def construction(candidate):
    if candidate not in CANDIDATES:raise ValueError('Unknown two-lane candidate')
    base=parameters('probe_2',candidate)
    return {**base,'case':CASE,'case_id':ASSIGNMENT+'__'+CASE,
            'comparison_variable':'same_direction_lane_count',
            'same_direction_lane_count':2,
            'road_variant':'two_same_direction_lanes',
            'authored_road_sha256':hashlib.sha256(two_lane_open_drive().encode()).hexdigest(),
            'status':'planned_native_construction',
            'physical_lane_availability_verified':False}


def check():
    root=ET.fromstring(two_lane_open_drive())
    lanes=root.findall('road/lanes/laneSection/right/lane')
    if [(int(lane.get('id')),float(lane.find('width').get('a'))) for lane in lanes]!=[(-1,4.),(-2,4.)]:
        raise ValueError('Authored two-lane Native road differs')
    variants={candidate:construction(candidate) for candidate in CANDIDATES}
    fixed=('case','case_id','target_gap_m','law_id','cell_id','actor','comparison_variable',
           'same_direction_lane_count','road_variant','authored_road_sha256')
    if any(any(value[key]!=variants['primary'][key] for key in fixed) for value in variants.values()):
        raise ValueError('Two-lane candidate changes statutory mechanism')
    if any(value['knobs']['rate_hz']!=20 or value['knobs']['duration_s']!=24 or
           value['target_gap_m']!=140 for value in variants.values()):
        raise ValueError('Two-lane candidate timing or gap differs')
    hashes={candidate:hashlib.sha256(json.dumps(value,sort_keys=True).encode()).hexdigest()
            for candidate,value in variants.items()}
    if len(set(hashes.values()))!=4:
        raise ValueError('Two-lane candidates are not distinct')
    triggers={variants[name]['fallback_trigger']['metric'] for name in CANDIDATES[1:]}
    if len(triggers)!=3:raise ValueError('Two-lane fallback triggers are not distinct')
    return {'passed':True,'case_id':ASSIGNMENT+'__'+CASE,
            'candidate_sha256':hashes,'same_direction_lane_ids':[-1,-2],
            'physical_lane_availability_verified':False,
            'selected_delivery_claimed':False}


if __name__=='__main__':print(json.dumps(check(),sort_keys=True))

"""Owned-endpoint trajectory requests for the planned one-lane passing case.

The saved passing measurement, rather than this request, decides whether a
capture contains a complete overtake and return. No physical clearance is
inferred from the requested trajectory.
"""
from __future__ import annotations
import hashlib
import json

CASE='passing_overtake'
ASSIGNMENT='training__C102372__NRS-484B-127-2__heavy_vehicle_driver'
CANDIDATES=('primary','fallback1','fallback2','fallback3')
BASE={'ego_speed_mps':12.,'lead_speed_mps':8.,'opposing_center_y_m':2.,
      'enter_start_s':2.,'enter_end_s':4.,'return_start_s':16.,
      'return_end_s':18.,'rate_hz':20,'duration_s':24}
CHANGES={
    'primary':{},
    'fallback1':{'ego_speed_mps':12.5},
    'fallback2':{'opposing_center_y_m':2.3},
    'fallback3':{'enter_start_s':1.5,'enter_end_s':3.5,
                 'return_start_s':17.,'return_end_s':19.},
}
TRIGGERS={
    'fallback1':{'metric':'final_center_offset_m','op':'<','threshold':50.,
                 'source':'480 source-hashed original Native truck body centers and frame times'},
    'fallback2':{'metric':'minimum_body_clearance_m','op':'<','threshold':1.5,
                 'source':'480 source-hashed original Native 80-inch truck body footprints'},
    'fallback3':{'metric':'opposing_lane_frames','op':'<','threshold':300,
                 'source':'480 source-hashed original Native lane/body frame joins'},
}


def construction(candidate):
    if candidate not in CANDIDATES:raise ValueError('Unknown passing candidate')
    return {'case':CASE,'case_id':ASSIGNMENT+'__'+CASE,'candidate':candidate,
            'law_id':'NRS-484B-127-2','cell_id':'C102372',
            'actor':'heavy_vehicle_driver','comparison_variable':'passing_sequence_observed',
            'knobs':BASE|CHANGES[candidate],
            'fallback_trigger':TRIGGERS.get(candidate),
            'status':'planned_native_construction',
            'physical_opposing_clearance_verified':False,
            'legal_verdict_claimed':False}


def request(candidate,frame):
    """Return 20 Hz speed/lateral requests; a saved original trace must verify them."""
    if not isinstance(frame,int) or not 0<=frame<480:
        raise ValueError('Full passing frame index required')
    k=construction(candidate)['knobs'];t=frame/k['rate_hz'];y0=-2.;y1=k['opposing_center_y_m']
    if t<k['enter_start_s']:y=y0
    elif t<k['enter_end_s']:
        y=y0+(y1-y0)*(t-k['enter_start_s'])/(k['enter_end_s']-k['enter_start_s'])
    elif t<k['return_start_s']:y=y1
    elif t<k['return_end_s']:
        y=y1+(y0-y1)*(t-k['return_start_s'])/(k['return_end_s']-k['return_start_s'])
    else:y=y0
    return {'time_s':t,'ego_speed_mps':k['ego_speed_mps'],
            'lead_speed_mps':k['lead_speed_mps'],'ego_target_y_m':round(y,6),
            'intended_lane_id':1 if y>=0 else -1}


def check():
    variants={name:construction(name) for name in CANDIDATES}
    fixed=('case','case_id','law_id','cell_id','actor','comparison_variable')
    if any(any(v[key]!=variants['primary'][key] for key in fixed)
           for v in variants.values()):raise ValueError('Passing statutory identity changed')
    if len({hashlib.sha256(json.dumps(v,sort_keys=True).encode()).hexdigest()
            for v in variants.values()})!=4:
        raise ValueError('Passing candidates are not distinct')
    if len({TRIGGERS[n]['metric'] for n in CANDIDATES[1:]})!=3:
        raise ValueError('Passing fallback triggers repeat')
    for name in CANDIDATES:
        k=variants[name]['knobs']
        if not (k['rate_hz']==20 and k['duration_s']==24 and
                0<k['enter_start_s']<k['enter_end_s']<
                k['return_start_s']<k['return_end_s']<24 and
                1.3<k['opposing_center_y_m']<2.7 and
                0<k['lead_speed_mps']<k['ego_speed_mps']):
            raise ValueError('Passing trajectory timing or lane differs')
        if request(name,0)['intended_lane_id']!=-1 or \
           request(name,479)['intended_lane_id']!=-1 or \
           request(name,200)['intended_lane_id']!=1:
            raise ValueError('Passing trajectory does not depart and return')
    return {'passed':True,'case_id':ASSIGNMENT+'__'+CASE,
            'candidate_count':4,'fallback_metric_count':3,
            'original_capture_claimed':False}

"""Source-bound fallback decisions for the planned passing-and-return case."""
from __future__ import annotations
import hashlib
import json
from pathlib import Path
from passing_carveout import measure
from passing_engineering import ASSIGNMENT,CASE,TRIGGERS


def digest(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':')).encode()).hexdigest()


def extract(source_dir):
    source=Path(source_dir)
    context=json.loads((source/'following_context.json').read_text())
    if context.get('case_id')!=ASSIGNMENT+'__'+CASE:
        raise ValueError('Passing source case identity differs')
    value=measure(source)
    metrics={name:value[name] for name in ('final_center_offset_m',
        'minimum_body_clearance_m','opposing_lane_frames')}
    result={'format':'c102372-passing-trigger-v1','case_id':ASSIGNMENT+'__'+CASE,
            'metrics':metrics,'metric_sha256':digest(metrics),
            'sources':value['sources'],'source_kind':value['source_kind'],
            'passing_sequence_observed':value['passing_sequence_observed'],
            'physical_opposing_clearance_verified':False}
    return result


def decide(result,candidate,diagnostic=False):
    if candidate not in TRIGGERS:raise ValueError('Unknown passing fallback')
    if result.get('format')!='c102372-passing-trigger-v1' or \
       result.get('case_id')!=ASSIGNMENT+'__'+CASE or \
       result.get('metric_sha256')!=digest(result.get('metrics')) or \
       set(result.get('sources',{}))!={'native_samples.jsonl','following_context.json','road.xodr'}:
        raise ValueError('Passing fallback metric identity or digest differs')
    if result.get('source_kind')!='native_observation' and not diagnostic:
        raise ValueError('Original Native passing source required for dispatch')
    if result.get('source_kind') not in ('native_observation','synthetic_cpu_fixture'):
        raise ValueError('Unknown passing source kind')
    if result.get('physical_opposing_clearance_verified') is not False:
        raise ValueError('Passing physical clearance claim differs')
    trigger=TRIGGERS[candidate];number=result['metrics'].get(trigger['metric'])
    if not isinstance(number,(int,float)) or isinstance(number,bool):
        raise ValueError('Passing fallback metric missing')
    return number<trigger['threshold']

"""Law-preserving Native requests for the controlled no-passing case."""
from __future__ import annotations
import hashlib
import json

CASE='passing_hold'
ASSIGNMENT='training__C102372__NRS-484B-127-2__heavy_vehicle_driver'
CANDIDATES=('primary','fallback1','fallback2','fallback3')
BASE={'ego_speed_mps':8.,'lead_speed_mps':8.,'target_gap_m':26.,
      'gap_gain':.25,'lane_center_gain':.5,'rate_hz':20,'duration_s':24}
CHANGES={'primary':{},'fallback1':{'ego_speed_mps':7.5},
         'fallback2':{'lead_speed_mps':8.5,'gap_gain':.4},
         'fallback3':{'lane_center_gain':1.}}
TRIGGERS={
    'fallback1':{'metric':'minimum_body_clearance_m','op':'<','threshold':20.,
                 'source':'source-hashed original Native truck body footprints over 480 frames'},
    'fallback2':{'metric':'maximum_speed_difference_mps','op':'>','threshold':1.,
                 'source':'source-hashed original Native ego and lead velocities over 480 frames'},
    'fallback3':{'metric':'maximum_lane_center_error_m','op':'>','threshold':.3,
                 'source':'source-hashed original Native ego body centers over 480 frames'},
}


def construction(candidate):
    if candidate not in CANDIDATES:raise ValueError('Unknown hold candidate')
    return {'case':CASE,'case_id':ASSIGNMENT+'__'+CASE,'candidate':candidate,
            'law_id':'NRS-484B-127-2','cell_id':'C102372',
            'actor':'heavy_vehicle_driver','comparison_variable':'passing_sequence_observed',
            'knobs':BASE|CHANGES[candidate],'fallback_trigger':TRIGGERS.get(candidate),
            'status':'planned_native_construction','legal_verdict_claimed':False}


def speed_requests(candidate,gap):
    k=construction(candidate)['knobs']
    ego=max(.5,min(k['ego_speed_mps']+2,
                   k['ego_speed_mps']+k['gap_gain']*(gap-k['target_gap_m'])))
    return ego,k['lead_speed_mps']


def check():
    variants={name:construction(name) for name in CANDIDATES}
    fixed=('case','case_id','law_id','cell_id','actor','comparison_variable')
    if any(any(v[key]!=variants['primary'][key] for key in fixed)
           for v in variants.values()):raise ValueError('Hold statutory identity changed')
    if len({hashlib.sha256(json.dumps(v,sort_keys=True).encode()).hexdigest()
            for v in variants.values()})!=4:
        raise ValueError('Hold candidates are not distinct')
    if len({TRIGGERS[n]['metric'] for n in CANDIDATES[1:]})!=3:
        raise ValueError('Hold fallback triggers repeat')
    for name in CANDIDATES:
        k=variants[name]['knobs']
        if not (k['rate_hz']==20 and k['duration_s']==24 and
                0<k['ego_speed_mps']<12 and 0<k['lead_speed_mps']<12 and
                k['target_gap_m']>=20 and 0<k['gap_gain']<1 and
                0<k['lane_center_gain']<=1):
            raise ValueError('Hold request leaves safe bounds')
        if speed_requests(name,26.)[0]<=0:
            raise ValueError('Hold request lacks positive velocity')
    return {'passed':True,'case_id':ASSIGNMENT+'__'+CASE,
            'candidate_count':4,'fallback_metric_count':3,
            'original_capture_claimed':False}

"""Native requests for the controlled steady/lead-braking conditions pair."""
from __future__ import annotations
import hashlib
import json

ASSIGNMENT='training__C102372__NRS-484B-127-2__heavy_vehicle_driver'
CASES=('conditions_steady','conditions_lead_brake')
CANDIDATES=('primary','fallback1','fallback2','fallback3')
BASE={'ego_speed_mps':8.,'lead_speed_mps':8.,'initial_horizontal_gap_m':155.,
      'gap_gain':.25,'ego_brake_start_s':9.,'ego_brake_stop_s':13.,
      'lead_brake_start_s':8.,'lead_brake_stop_s':10.,
      'obstacle_x_m':285.,'rate_hz':20,'duration_s':24}
CHANGES={
    'conditions_steady':{
        'primary':{},'fallback1':{'initial_horizontal_gap_m':160.},
        'fallback2':{'ego_speed_mps':7.5},'fallback3':{'gap_gain':.5}},
    'conditions_lead_brake':{
        'primary':{},'fallback1':{'initial_horizontal_gap_m':160.},
        'fallback2':{'ego_brake_stop_s':12.},'fallback3':{'obstacle_x_m':295.}},
}
TRIGGERS={
    'conditions_steady':{
        'fallback1':{'metric':'minimum_surface_gap_m','op':'<','threshold':160.,
                     'source':'480 source-hashed Native truck bodies and hill-crest road surface'},
        'fallback2':{'metric':'surface_gap_compression_m','op':'>','threshold':1.,
                     'source':'480 source-hashed Native body/road-arc gap samples'},
        'fallback3':{'metric':'maximum_speed_difference_mps','op':'>','threshold':1.,
                     'source':'480 source-hashed Native ego/lead velocity readbacks'}},
    'conditions_lead_brake':{
        'fallback1':{'metric':'minimum_surface_gap_m','op':'<','threshold':142.,
                     'source':'480 source-hashed Native truck bodies and hill-crest road surface'},
        'fallback2':{'metric':'surface_gap_compression_m','op':'>','threshold':15.,
                     'source':'480 source-hashed Native body/road-arc gap samples'},
        'fallback3':{'metric':'minimum_lead_obstacle_clearance_m','op':'<','threshold':20.,
                     'source':'480 source-hashed Native lead and stopped-obstacle body footprints'}},
}


def construction(case,candidate):
    if case not in CASES or candidate not in CANDIDATES:
        raise ValueError('Unknown conditions case/candidate')
    return {'case':case,'case_id':ASSIGNMENT+'__'+case,'candidate':candidate,
            'law_id':'NRS-484B-127-2','cell_id':'C102372','actor':'heavy_vehicle_driver',
            'comparison_variable':'lead_braking_gap_compression_observed',
            'knobs':BASE|CHANGES[case][candidate],
            'fallback_trigger':TRIGGERS[case].get(candidate),
            'status':'planned_native_construction',
            'physical_conditions_permit_verified':False,'legal_verdict_claimed':False}


def request(case,candidate,frame):
    if not isinstance(frame,int) or not 0<=frame<480:
        raise ValueError('Full conditions frame index required')
    k=construction(case,candidate)['knobs'];t=frame/20
    if case=='conditions_steady':
        return {'time_s':t,'ego_speed_mps':k['ego_speed_mps'],
                'lead_speed_mps':k['lead_speed_mps'],
                'stopped_obstacle_requested':False}
    def braking(speed,start,stop):
        if t<=start:return speed
        if t>=stop:return 0.
        return round(speed*(stop-t)/(stop-start),6)
    return {'time_s':t,
            'ego_speed_mps':braking(k['ego_speed_mps'],k['ego_brake_start_s'],
                                   k['ego_brake_stop_s']),
            'lead_speed_mps':braking(k['lead_speed_mps'],k['lead_brake_start_s'],
                                    k['lead_brake_stop_s']),
            'stopped_obstacle_requested':True}


def check():
    for case in CASES:
        variants={candidate:construction(case,candidate) for candidate in CANDIDATES}
        fixed=('case','case_id','law_id','cell_id','actor','comparison_variable')
        if any(any(v[key]!=variants['primary'][key] for key in fixed)
               for v in variants.values()):
            raise ValueError('Conditions statutory identity changed')
        if len({hashlib.sha256(json.dumps(v,sort_keys=True).encode()).hexdigest()
                for v in variants.values()})!=4 or \
           len({TRIGGERS[case][n]['metric'] for n in CANDIDATES[1:]})!=3:
            raise ValueError('Conditions candidates/triggers repeat')
        for candidate,v in variants.items():
            k=v['knobs']
            if not (k['rate_hz']==20 and k['duration_s']==24 and
                    k['initial_horizontal_gap_m']>=155 and
                    0<k['ego_speed_mps']<=8 and 0<k['lead_speed_mps']<=8 and
                    0<k['gap_gain']<=.5 and
                    8<=k['lead_brake_start_s']<k['lead_brake_stop_s']<=10 and
                    9<=k['ego_brake_start_s']<k['ego_brake_stop_s']<=13 and
                    285<=k['obstacle_x_m']<=295):
                raise ValueError('Conditions request leaves controlled bounds')
            if request(case,candidate,0)['stopped_obstacle_requested']!=(
                    case=='conditions_lead_brake'):
                raise ValueError('Conditions event request differs')
    return {'passed':True,'case_count':2,'candidate_count':8,
            'fallback_metric_count':6,'original_capture_claimed':False}

